import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // ✅ استيراد useNavigate

export default function RestaurantBooking() {
  const [formData, setFormData] = useState({
    location: '',
    cuisine: '',
    date: '',
    time: '',
    partySize: ''
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');
    try {
      const response = await fetch('/api/tables', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (data.length > 0) {
        navigate('/results', { state: { tables: data } });
      } else {
        setMessage('عذرًا، الحجز فلل ولا توجد طاولات متاحة.');
      }
    } catch (error) {
      console.error('خطأ في البحث:', error);
      setMessage('حدث خطأ أثناء البحث. يرجى المحاولة مرة أخرى.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container py-5">
      <h1 className="text-center mb-5 text-white" style={{ textShadow: '0 0 10px rgba(0,0,0,0.7)' }}>
        BOOK A TABLE
      </h1>

      <form onSubmit={handleSearch}>
        {message && (
          <div className={`alert ${message.includes('خطأ') ? 'alert-danger' : 'alert-success'}`} role="alert">
            {message}
          </div>
        )}

        <div className="row g-3 align-items-end">
          <div className="col-md">
            <label htmlFor="location" className="form-label text-white">Location:</label>
            <input
              type="text"
              className="form-control"
              id="location"
              name="location"
              value={formData.location}
              onChange={handleInputChange}
              placeholder="اختر الموقع"
              required
            />
          </div>

          <div className="col-md">
            <label htmlFor="cuisine" className="form-label text-white">Cuisine:</label>
            <input
              type="text"
              className="form-control"
              id="cuisine"
              name="cuisine"
              value={formData.cuisine}
              onChange={handleInputChange}
              placeholder="أدخل نوع المطبخ"
              required
            />
          </div>

          <div className="col-md">
            <label htmlFor="date" className="form-label text-white">Date:</label>
            <input
              type="date"
              className="form-control"
              id="date"
              name="date"
              value={formData.date}
              onChange={handleInputChange}
              min={new Date().toISOString().split('T')[0]}
              required
            />
          </div>

          <div className="col-md">
            <label htmlFor="time" className="form-label text-white">Time:</label>
            <input
              type="time"
              className="form-control"
              id="time"
              name="time"
              value={formData.time}
              onChange={handleInputChange}
              required
            />
          </div>

          <div className="col-md">
            <label htmlFor="partySize" className="form-label text-white">Party Size:</label>
            <input
              type="number"
              className="form-control"
              id="partySize"
              name="partySize"
              value={formData.partySize}
              onChange={handleInputChange}
              placeholder="عدد الأشخاص"
              min="1"
              required
            />
          </div>

          <div className="col-md-auto">
            <button type="submit" className="btn btn-success w-100" disabled={loading}>
              {loading ? (
                <>
                  <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                  Searching...
                </>
              ) : (
                'SEARCH'
              )}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
}
